// bit0 = current, bit1 = next
live = count of neighbors with (cell & 1) == 1
if (cell & 1) and live in {2,3}: cell |= 2   // stays/becomes live
if !(cell & 1) and live == 3: cell |= 2       // reproduction
// final pass: cell >>= 1

